 if(!hidden.size)return model;
 const group=rows=>{const keep=[],omitted=[];for(const row of rows||[])(hidden.has(row.name)||row.name==='Non-person source IDs'||row.name===otherName?omitted:keep).push(row);if(!omitted.length)return keep;const other={name:otherName};
  const keys=[...new Set(omitted.flatMap(row=>Object.keys(row)))];for(const key of keys){if(key==='name')continue;const values=omitted.map(row=>row[key]);if(values.every(v=>typeof v==='number'||v===null)){other[key]=values.some(v=>v===null)?null:values.reduce((sum,v)=>sum+Math.round(v*100),0)/100;}}
  for(const key of ['sales','profit'])if(('prior_'+key) in other){const before=other['prior_'+key],now=other[key];other[key+'_delta']=before===null||now===null?null:Math.round((now-before)*100)/100;other[key+'_change']=before===null||now===null?'Unavailable':before!==0?((now-before)/Math.abs(before)*100).toFixed(1)+'%':now>0?'New':'N/A';}
  return [...keep,other];};
