 const pie=(values,label)=>{if(values.some(r=>r.value===null))return `<div class="sales-mix"><b>${esc(label)}</b><p>Unavailable — incomplete invoice coverage.</p></div>`;const positive=values.filter(r=>r.value>0),total=positive.reduce((n,r)=>n+r.value,0);let angle=-Math.PI/2;return `<div class="sales-mix"><b>${esc(label)}</b><svg viewBox="0 0 630 205" role="img" aria-label="${esc(label)}">${positive.map((r,i)=>{const start=angle;angle+=r.value/total*Math.PI*2;const cx=315,cy=102.5,rad=78,x=a=>cx+rad*Math.cos(a),yy=a=>cy+rad*Math.sin(a),mid=(start+angle)/2;return `${positive.length===1?`<circle cx="${cx}" cy="${cy}" r="${rad}" fill="${mixColors[i%mixColors.length]}" data-value="${r.value}"/>`:`<path d="M${cx} ${cy} L${x(start)} ${yy(start)} A${rad} ${rad} 0 ${angle-start>Math.PI?1:0} 1 ${x(angle)} ${yy(angle)} Z" fill="${mixColors[i%mixColors.length]}" data-value="${r.value}"/>`}<text x="${315+116*Math.cos(mid)}" y="${145+116*Math.sin(mid)}" text-anchor="${Math.cos(mid)>0?'start':'end'}" font-size="9">${values.length===2?`<tspan x="${315+116*Math.cos(mid)}" dy="-8" font-size="12" font-weight="bold">${esc(r.name)}</tspan><tspan x="${315+116*Math.cos(mid)}" dy="18" font-size="11">$${Math.round(r.value).toLocaleString('en-US')}</tspan>`:esc(r.name)}</text>`}).join('')}</svg></div>`;};
