function reportFilename(month){const [year,number]=month.split('-').map(Number);return 'SMI Salesperson Report '+new Date(Date.UTC(year,number-1,1)).toLocaleString('en-US',{month:'long',timeZone:'UTC'})+' '+year;}
function install(getSnapshot,config){
 const select=document.getElementById('monthlyReportMonth'),button=document.getElementById('monthlyReportPdf');
 function sync(){const s=getSnapshot();const eligible=k=>{if(!Object.hasOwn(s,'gl_financials'))return true;if(!s.gl_financials||s.gl_financials.version!=='smi-gl-financial-v1'||!s.gl_financials.periods)return false;const end=new Date(Date.UTC(Number(k.slice(0,4)),Number(k.slice(5)),0)).toISOString().slice(0,10);if(end>s.as_of||end>s.gl_financials.as_of)return false;for(const year of [Number(k.slice(0,4))-1,Number(k.slice(0,4))])for(let n=1;n<=Number(k.slice(5));n++)if(!s.gl_financials.periods[year+'-'+String(n).padStart(2,'0')])return false;return true;};const keys=Object.keys(s?.months||{}).filter(k=>k<=s.as_of.slice(0,7)&&eligible(k)).sort().reverse();const old=select.value;select.replaceChildren(...keys.map(k=>{const o=document.createElement('option');o.value=k;o.textContent=k;return o}));if(keys.includes(old))select.value=old;button.disabled=!keys.length;download.disabled=button.disabled}
 const download=document.createElement('button');download.type='button';download.className=button.className;download.id='monthlyReportDownload';download.textContent='Download monthly PDF';button.after(download);download.onclick=()=>{try{const model=build(getSnapshot(),select.value,config);root.MonthlyReportPDF.create(model).save(reportFilename(model.month)+'.pdf')}catch(e){root.alert('PDF download failed: '+e.message+'; Print / Save PDF remains available.')}};
 select.addEventListener('focus',sync);button.onclick=()=>{try{const model=build(getSnapshot(),select.value,config);const target=root.open('about:blank','_blank');if(!target){root.alert('Allow pop-ups to open the monthly report.');return}target.document.open();target.document.write(render(model));target.document.close()}catch(e){root.alert(e.message)}};
 return {sync};
}
